    """Checks if the DataFrame's date range is reasonable."""
    if 'REF_DATE' not in df.columns or df['REF_DATE'].isnull().all():
        return False
    try:
        years = df['REF_DATE'].dt.year
        return (years.min() <= max_year) and (years.max() >= min_year)
    except:
        return False
